for ch in "abc3def":
    if ch in "0123456789":
        print(ch)
        break

for i in range(1, 11):
    if i % 2 == 0:
        continue
    print(i)

while True:
    cmd = input("Команда: ")
    if cmd == "стоп":
        break
    print(cmd)

for row in range(1, 4):
    for col in range(1, 4):
        print(row * col, end="  ")
    print()

